@Composable
fun TransactionEntryScreen(type:String,sessionId:String,driverId:String,vehicleId:String,onSaved:(String)->Unit,onCancel:()->Unit){
 val entryType=runCatching{EntryType.valueOf(type)}.getOrElse{EntryType.TRIP};val context=LocalContext.current;val owner=LocalLifecycleOwner.current;val scope=rememberCoroutineScope();val auth=remember{AuthRepository(context)};val db=remember{CabDatabase.get(context)};val repo=remember{TripLocalRepository(context)}
 var activeTrip by remember{mutableStateOf<LocalTrip?>(null)};var startedAt by remember{mutableStateOf<String?>(null)};var startOdo by remember{mutableStateOf("")};var endOdo by remember{mutableStateOf("")};var fare by remember{mutableStateOf("")};var charges by remember{mutableStateOf("0")};var payment by remember{mutableStateOf("UPI")};var status by remember{mutableStateOf("COMPLETED")};var pickup by remember{mutableStateOf("")};var dropoff by remember{mutableStateOf("")};var notes by remember{mutableStateOf("")};var fuelType by remember{mutableStateOf("CNG")};var quantity by remember{mutableStateOf("")};var unit by remember{mutableStateOf("KG")};var rate by remember{mutableStateOf("")};var amount by remember{mutableStateOf("")};var category by remember{mutableStateOf<ExpenseCategoryOption?>(null)};var categories by remember{mutableStateOf<List<ExpenseCategoryOption>>(emptyList())};var platforms by remember{mutableStateOf<List<PlatformOption>>(emptyList())};var platform by remember{mutableStateOf<PlatformOption?>(null)};var menu by remember{mutableStateOf<String?>(null)};var busy by remember{mutableStateOf(false)};var error by remember{mutableStateOf("")};var gps by remember{mutableStateOf<LocationSnapshot?>(null)};var gpsStatus by remember{mutableStateOf("Getting GPS location…")}
 fun gps(){val p=FusedLocationProvider(context);if(!p.isLocationEnabled()){gps=null;gpsStatus="Location services are OFF. Turn on Location to continue.";runCatching{context.startActivity(Intent(Settings.ACTION_LOCATION_SOURCE_SETTINGS))};return};gpsStatus="Getting a precise GPS fix…";p.currentLocation{l,e->gps=l;gpsStatus=when{l?.isUsable()==true->"GPS ready • accuracy ±${l.accuracyMeters.toInt()} m";l!=null->"GPS found, but accuracy is above 50 m. Waiting for a better fix…";else->"GPS unavailable${e?.let{": $it"}?:""}."}}}
 fun loadTrip(){scope.launch{activeTrip=withContext(Dispatchers.IO){db.localTripDao().active(sessionId)};startedAt=activeTrip?.let{withContext(Dispatchers.IO){db.pendingTransactionDao().find(it.clientTransactionId)}?.let{p->Regex("\\\"startedAt\\\"\\s*:\\s*\\\"([^\\\"]+)\\\"").find(p.payloadJson)?.groupValues?.get(1)}}}}
 LaunchedEffect(Unit){gps();if(entryType==EntryType.TRIP)loadTrip()};DisposableEffect(owner){val o=LifecycleEventObserver{_,e->if(e==Lifecycle.Event.ON_RESUME){gps();if(entryType==EntryType.TRIP)loadTrip()}};owner.lifecycle.addObserver(o);onDispose{owner.lifecycle.removeObserver(o)}}
 LaunchedEffect(entryType){val token=withContext(Dispatchers.IO){auth.refreshIfNeeded()}.getOrNull()?.accessToken?:return@LaunchedEffect;if(entryType==EntryType.TRIP){val r=withContext(Dispatchers.IO){PlatformRepository(BuildConfig.API_BASE_URL,token).load()};if(r.isSuccess){platforms=r.getOrNull().orEmpty();platform=platforms.firstOrNull()}};if(entryType==EntryType.EXPENSE){val r=withContext(Dispatchers.IO){ExpenseCategoryRepository(BuildConfig.API_BASE_URL,token).load()};if(r.isSuccess)categories=r.getOrNull().orEmpty()}}
 val q=quantity.toDoubleOrNull();val r=rate.toDoubleOrNull();val totalFuel=if(q!=null&&r!=null&&q>0&&r>=0)q*r else null;val active=entryType==EntryType.TRIP&&activeTrip!=null
 fun save(){if(busy)return;val loc=gps;if(loc?.isUsable()!=true){error="Precise fresh GPS (accuracy ≤50 m) is required.";gps();return};busy=true;error="";scope.launch{try{val id=when(entryType){EntryType.TRIP->{if(activeTrip==null){val s=startOdo.toDoubleOrNull()?:error("Enter starting odometer");repo.startTrip(sessionId,driverId,vehicleId,s,loc,pickup.trim().ifBlank{null},platform?.id,notes.trim().ifBlank{null})}else{val e=endOdo.toDoubleOrNull()?:error("Enter ending odometer");val f=fare.toDoubleOrNull()?:error("Enter fare");repo.endTrip(activeTrip!!.clientTransactionId,sessionId,driverId,vehicleId,e,f,loc,payment,charges.toDoubleOrNull()?:0.0,status,pickup.trim().ifBlank{null},dropoff.trim().ifBlank{null},platform?.id,notes.trim().ifBlank{null})}}
 EntryType.FUEL->{val o=startOdo.toDoubleOrNull()?:error("Enter odometer");val n=q?:error("Enter quantity");val rr=r?:error("Enter rate");FuelLocalRepository(context).queueFuel(sessionId,driverId,vehicleId,fuelType.trim(),o,n,unit.trim(),rr,totalFuel?:error("Enter valid quantity and rate"),payment,notes=notes.trim().ifBlank{null},location=loc)}
 EntryType.EXPENSE->{val a=amount.toDoubleOrNull()?:error("Enter amount");ExpenseLocalRepository(context).queueExpense(sessionId,driverId,vehicleId,a,category?.id,payment,odometer=startOdo.toDoubleOrNull(),notes=notes.trim().ifBlank{null},location=loc)}};SyncScheduler.enqueue(context,BuildConfig.API_BASE_URL);if(entryType==EntryType.TRIP)loadTrip();onSaved(id)}catch(e:Exception){error=e.message?:"Unable to save. Please try again."}finally{busy=false}}}
 Column(Modifier.fillMaxSize().verticalScroll(rememberScrollState()).padding(bottom=24.dp),verticalArrangement=Arrangement.spacedBy(12.dp)){CabHeader(if(active)"Trip in progress" else when(entryType){EntryType.TRIP->"Start a trip";EntryType.FUEL->"Record fuel";EntryType.EXPENSE->"Record an expense"},"Trip start time and odometer are stored automatically when you start.",onBack=onCancel);Column(Modifier.padding(horizontal=16.dp),verticalArrangement=Arrangement.spacedBy(12.dp)){Surface(shape=RoundedCornerShape(14.dp),color=CabPurpleSoft){Text("Saved on phone first • sync starts automatically",Modifier.fillMaxWidth().padding(12.dp),color=CabPurple,fontWeight=FontWeight.SemiBold)};Surface(shape=RoundedCornerShape(14.dp),color=if(gps?.isUsable()==true)CabGreenSoft else CabAmberSoft){Text(gpsStatus,Modifier.fillMaxWidth().padding(13.dp),color=if(gps?.isUsable()==true)CabGreen else CabAmber,fontWeight=FontWeight.SemiBold)};CabCard{when(entryType){EntryType.TRIP->{if(active){Text("Trip started ${startedAt?.let{runCatching{Duration.between(Instant.parse(it),Instant.now()).toMinutes()}.getOrNull()}?:0} min ago",style=MaterialTheme.typography.titleLarge,fontWeight=FontWeight.Bold);Text("Start odometer: ${activeTrip!!.startOdometer.toInt()} km",color=CabGray);Text("This trip remains active after closing the app.",color=CabGray);OutlinedTextField(endOdo,{endOdo=it},label={Text("Ending odometer (km)")},modifier=Modifier.fillMaxWidth(),singleLine=true,shape=RoundedCornerShape(14.dp));OutlinedTextField(fare,{fare=it},label={Text("Gross fare (₹)")},modifier=Modifier.fillMaxWidth(),singleLine=true,shape=RoundedCornerShape(14.dp));OutlinedTextField(charges,{charges=it},label={Text("Additional charges (₹)")},modifier=Modifier.fillMaxWidth(),singleLine=true,shape=RoundedCornerShape(14.dp));Box{OutlinedButton({menu="pay"},Modifier.fillMaxWidth()){Text("Payment: $payment")};DropdownMenu(menu=="pay",{menu=null}){paymentMethods.forEach{p->DropdownMenuItem({Text(p)},{payment=p;menu=null})}}};OutlinedTextField(dropoff,{dropoff=it},label={Text("Drop (optional)")},modifier=Modifier.fillMaxWidth(),shape=RoundedCornerShape(14.dp))}else{CabSectionLabel("START TRIP");OutlinedTextField(startOdo,{startOdo=it},label={Text("Starting odometer (km)")},modifier=Modifier.fillMaxWidth(),singleLine=true,shape=RoundedCornerShape(14.dp));OutlinedTextField(pickup,{pickup=it},label={Text("Pickup (optional)")},modifier=Modifier.fillMaxWidth(),shape=RoundedCornerShape(14.dp));Text("Press Start Trip now. The app records the exact start time, GPS and start odometer so you never need to remember them.",color=CabGray,style=MaterialTheme.typography.bodySmall)}};EntryType.FUEL->{CabSectionLabel("FUEL");OutlinedTextField(startOdo,{startOdo=it},label={Text("Odometer (km)")},modifier=Modifier.fillMaxWidth(),singleLine=true);OutlinedTextField(fuelType,{fuelType=it},label={Text("Fuel type")},modifier=Modifier.fillMaxWidth(),singleLine=true);Row(horizontalArrangement=Arrangement.spacedBy(8.dp)){OutlinedTextField(quantity,{quantity=it},label={Text("Quantity")},modifier=Modifier.weight(1f),singleLine=true);OutlinedTextField(unit,{unit=it},label={Text("Unit")},modifier=Modifier.weight(1f),singleLine=true)};OutlinedTextField(rate,{rate=it},label={Text("Rate (₹)")},modifier=Modifier.fillMaxWidth(),singleLine=true);Text("Total: ${totalFuel?.let{"₹%.2f".format(it)}?:"—"}",fontWeight=FontWeight.Bold)};EntryType.EXPENSE->{CabSectionLabel("EXPENSE");OutlinedTextField(amount,{amount=it},label={Text("Amount (₹)")},modifier=Modifier.fillMaxWidth(),singleLine=true);OutlinedTextField(startOdo,{startOdo=it},label={Text("Odometer (optional)")},modifier=Modifier.fillMaxWidth(),singleLine=true)}};OutlinedTextField(notes,{notes=it},label={Text("Notes (optional)")},modifier=Modifier.fillMaxWidth(),minLines=2)};if(error.isNotBlank())Text(error,color=MaterialTheme.colorScheme.error);CabPrimaryButton(if(active)"End Trip" else if(entryType==EntryType.TRIP)"Start Trip" else "Save entry",enabled=!busy&&gps?.isUsable()==true,onClick={save()});if(active)Text("Need fuel or another expense during this trip? Go back to the session and add it anytime. The trip will remain active.",color=CabGray,style=MaterialTheme.typography.bodySmall);CabSecondaryButton("Back to session",enabled=!busy,onClick=onCancel)}}}
